const r=t=>new Date(t.replace(" ","T"));function a(t){if(!t)return"";const o=(Date.now()-r(t).getTime())/1e3;if(o<60)return"just now";if(o<3600)return`${Math.floor(o/60)} min ago`;if(o<86400)return`${Math.floor(o/3600)} h ago`;const e=Math.floor(o/86400);return e===1?"yesterday":e<7?`${e} days ago`:r(t).toLocaleDateString(void 0,{day:"numeric",month:"short"})}function i(t){const o=r(t),e=new Date,n=new Date(Date.now()+864e5);return o.toDateString()===e.toDateString()?"Today":o.toDateString()===n.toDateString()?"Tomorrow":o.toLocaleDateString(void 0,{weekday:"long",day:"numeric",month:"short"})}function c(t){return r(t).toLocaleTimeString(void 0,{hour:"numeric",minute:"2-digit"})}function u(t){return t.split(/\s+/).filter(Boolean).slice(0,2).map(o=>{var e;return(e=o[0])==null?void 0:e.toUpperCase()}).join("")}function s(t){return t===t.toUpperCase()?t.toLowerCase().replace(/\b\w/g,o=>o.toUpperCase()):t}export{c,i as d,u as i,s as n,a as t};
